\[
 R_{n,\epsilon}^{\mathrm{DP},K}
 =\inf_{T_{\mathrm{DP}}:\,\epsilon\text{-DP}}
   \sup_{P\in\mathcal P_K}
   \mathbb E_{P^{\otimes n},T_{\mathrm{DP}}}
   |T_{\mathrm{DP}}(D_n)-\theta(P)|,
\]
where \(T_{\mathrm{DP}}\) is a Markov kernel from \(\mathcal O^n\) to
\([-2,2]\), and privacy is required for every replacement-neighbor pair
\(D_n\sim_1D_n'\).
